python3 -c "
import json
with open('/app/resources/treasury_bulletin_2011_09.json', 'r') as f:
    data = json.load(f)

# Search for USCC tables or denomination info
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'USCC' in str(k) or 'denomination' in str(k).lower() or 'number' in str(k).lower():
                print(f'{path}.{k}: {str(v)[:200]}')
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search(item, f'{path}[{i}]')

search(data)
" 2>/dev/null | head -50

python3 -c "
import json
with open('/app/resources/treasury_bulletin_2011_09.json', 'r') as f:
    data = json.load(f)

# Search for June 30, 2011
def search(obj, path='', depth=0):
    if depth > 5:
        return
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'June 30, 2011' in str(v):
                print(f'{path}.{k}: {str(v)[:300]}')
            search(v, f'{path}.{k}', depth+1)
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search(item, f'{path}[{i}]', depth+1)

search(data)
" 2>/dev/null | head -30
